def range_compress(values):
    if not values:
        return []
    uniq = sorted(set(values))
    n = len(uniq)
    if n == 1:
        return [uniq[0], uniq[0]]
    result = []
    start = uniq[0]
    prev = uniq[0]
    for i in range(1, n):
        cur = uniq[i]
        if cur == prev + 1:
            prev = cur
        else:
            if start == prev:
                result.append(start)
            else:
                result.append([start, prev])
            start = cur
            prev = cur
    if start == prev:
        result.append(start)
    else:
        result.append([start, prev])
    return result
